void* PRTOS_Memory_Alloc(size_t size)
{
  UNITY_LINE_TYPE cmock_line = TEST_LINE_NUM;
  CMOCK_PRTOS_Memory_Alloc_CALL_INSTANCE* cmock_call_instance;
  UNITY_SET_DETAIL(CMockString_PRTOS_Memory_Alloc);
  cmock_call_instance = (CMOCK_PRTOS_Memory_Alloc_CALL_INSTANCE*)CMock_Guts_GetAddressFor(Mock.PRTOS_Memory_Alloc_CallInstance);
  Mock.PRTOS_Memory_Alloc_CallInstance = CMock_Guts_MemNext(Mock.PRTOS_Memory_Alloc_CallInstance);
  if (Mock.PRTOS_Memory_Alloc_IgnoreBool)
  {
    UNITY_CLR_DETAILS();
    if (cmock_call_instance == NULL)
      return Mock.PRTOS_Memory_Alloc_FinalReturn;
    Mock.PRTOS_Memory_Alloc_FinalReturn = cmock_call_instance->ReturnVal;
    return cmock_call_instance->ReturnVal;
  }
  if (!Mock.PRTOS_Memory_Alloc_CallbackBool &&
      Mock.PRTOS_Memory_Alloc_CallbackFunctionPointer != NULL)
  {
    void* cmock_cb_ret = Mock.PRTOS_Memory_Alloc_CallbackFunctionPointer(size, Mock.PRTOS_Memory_Alloc_CallbackCalls++);
    UNITY_CLR_DETAILS();
    return cmock_cb_ret;
  }
  UNITY_TEST_ASSERT_NOT_NULL(cmock_call_instance, cmock_line, CMockStringCalledMore);
  cmock_line = cmock_call_instance->LineNumber;
  if (cmock_call_instance->CallOrder > ++GlobalVerifyOrder)
    UNITY_TEST_FAIL(cmock_line, CMockStringCalledEarly);
  if (cmock_call_instance->CallOrder < GlobalVerifyOrder)
    UNITY_TEST_FAIL(cmock_line, CMockStringCalledLate);
  if (!cmock_call_instance->ExpectAnyArgsBool)
  {
  if (!cmock_call_instance->IgnoreArg_size)
  {
    UNITY_SET_DETAILS(CMockString_PRTOS_Memory_Alloc,CMockString_size);
    UNITY_TEST_ASSERT_EQUAL_MEMORY(&cmock_call_instance->Expected_size, &size, sizeof(size_t), cmock_line, CMockStringMismatch);
  }
  }
  if (Mock.PRTOS_Memory_Alloc_CallbackFunctionPointer != NULL)
  {
    UNITY_SET_DETAIL(CMockString_PRTOS_Memory_Alloc);
    cmock_call_instance->ReturnVal = Mock.PRTOS_Memory_Alloc_CallbackFunctionPointer(size, Mock.PRTOS_Memory_Alloc_CallbackCalls++);
  }
  UNITY_CLR_DETAILS();
  return cmock_call_instance->ReturnVal;
}

void CMockExpectParameters_PRTOS_Memory_Alloc(CMOCK_PRTOS_Memory_Alloc_CALL_INSTANCE* cmock_call_instance, size_t size);
void CMockExpectParameters_PRTOS_Memory_Alloc(CMOCK_PRTOS_Memory_Alloc_CALL_INSTANCE* cmock_call_instance, size_t size)
{
  memcpy((void*)(&cmock_call_instance->Expected_size), (const void*)(&size),
         sizeof(size_t[sizeof(size) == sizeof(size_t) ? 1 : -1])); /* add size_t to :treat_as_array if this causes an error */
  cmock_call_instance->IgnoreArg_size = 0;
}

